// lib
// Project A: dependency-free model library (no MessagePack reference).
namespace ProjectA
{
    public class MyType
    {
        public int Id { get; set; }
        public string? Name { get; set; }
    }
}

// app
// Project B: references Project A + MessagePack (with MessagePack.SourceGenerator / analyzers).
// NOTE: not built or run here — written from reasoning about the generator, so the trigger is unverified.
// [Key]/[MessagePackFormatter] sit on members that are neither IPropertySymbol nor IFieldSymbol
// (an event and a method). Old: only the compiler's CS0592 "attribute not valid on this declaration".
// New: the member-type switch falls to its default arm and throws ArgumentOutOfRangeException,
// surfacing in the build as CS8785 (generator failed) / AD0001 (analyzer threw).
using System;
using MessagePack;
using MessagePack.Formatters;
using ProjectA;

namespace ProjectB
{
    public sealed class MyTypeFormatter : IMessagePackFormatter<MyType?>
    {
        public void Serialize(ref MessagePackWriter writer, MyType? value, MessagePackSerializerOptions options)
        {
            if (value is null) { writer.WriteNil(); return; }
            writer.WriteArrayHeader(2);
            writer.Write(value.Id);
            writer.Write(value.Name);
        }

        public MyType? Deserialize(ref MessagePackReader reader, MessagePackSerializerOptions options)
        {
            if (reader.TryReadNil()) return null;
            reader.ReadArrayHeader();
            return new MyType { Id = reader.ReadInt32(), Name = reader.ReadString() };
        }
    }

    [MessagePackObject]
    public partial class Envelope
    {
        [Key(0)]
        [MessagePackFormatter(typeof(MyTypeFormatter))]
        public MyType? Payload { get; set; }

        // Not a property, not a field: an event symbol carrying serialization attributes.
        [Key(1)]
        [MessagePackFormatter(typeof(MyTypeFormatter))]
        public event EventHandler? Changed;

        // Not a property, not a field: a method symbol carrying serialization attributes.
        [Key(2)]
        [MessagePackFormatter(typeof(MyTypeFormatter))]
        public MyType? Compute() => Payload;

        protected void OnChanged() => Changed?.Invoke(this, EventArgs.Empty);
    }

    public static class Program
    {
        public static void Main()
        {
            var bytes = MessagePackSerializer.Serialize(new Envelope { Payload = new MyType { Id = 1, Name = "a" } });
            Console.WriteLine(bytes.Length);
        }
    }
}
